import pathlib
root=pathlib.Path('/workspace/source')
keys=('native_policy','launch_guard','file_count','agent_observer','content_observer','files_sha256','RUNNING')
for p in sorted(root.glob('*.py'))+sorted((root/'native').glob('*')):
 text=p.read_text(errors='replace')
 print('====', p.name)
 for i,line in enumerate(text.splitlines(),1):
  if any(k in line for k in keys):
   print(f'{i}:{line[:200]}')
